pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let stream_progress = step_index as f64 / total_items as f64;
    let normalized_post_residual = (post_residual as f64 / bin_capacity as f64).powf(0.5);

    // Penalize large post_residuals early in the stream
    let mut score = -stream_progress * normalized_post_residual.powi(3);

    // Reward small post_residuals late in the stream
    if stream_progress > 0.5 {
        score += (1.0 - stream_progress) * normalized_post_residual.powi(2);
    }

    // Incorporate bin capacity and fitting_bins_count for better compaction
    let capacity_ratio = bin_residual as f64 / bin_capacity as f64;
    if capacity_ratio < 0.5 {
        score -= capacity_ratio.powi(3) * 0.1; // Penalize bins with low residual capacity
    } else {
        score += (1.0 - capacity_ratio).powi(2) * 0.2; // Reward bins with high residual capacity
    }

    // Lookahead for next item size to penalize large gaps
    if next_item_size > bin_capacity / 3 && post_residual < next_item_size {
        score -= ((next_item_size - post_residual) as f64 / bin_capacity as f64).powi(2);
    }

    // Penalize open bins count to minimize the number of bins used
    if open_bins_count > total_items / 10 {
        score -= (open_bins_count as f64 / total_items as f64).powi(3) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Favor bins with sufficient space for the current item
    if post_residual >= item_size * 3 / 4 {
        score -= 1.0;
    }

    // Penalize creating new bins unless necessary
    if open_bins_count == 0 && fitting_bins_count == 0 {
        score += 2.0;
    } else if fitting_bins_count == 1 {
        score -= 0.5;
    }

    // Favor using bins that are close to full capacity
    if bin_residual < bin_capacity / 4 {
        score += 1.0;
    }

    // Penalize creating empty bins
    if post_residual == 0 && fitting_bins_count == 0 {
        score += 3.0;
    }

    // Favor bins with similar residual to the mean
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score -= residual_diff * 0.1;

    // Penalize items that are too large for the remaining bin capacity
    if next_item_size > post_residual {
        score += 2.0;
    }

    // Lookahead to penalize bins that might not fit future items
    let future_fit = post_residual - next_item_size;
    if future_fit < item_size * 3 / 4 {
        score -= 1.5;
    }

    // Penalize bins with very small residuals
    if bin_residual < bin_capacity / 8 {
        score += 2.5;
    }

    score
}

