    } else if post_residual < 20.0 {
        score += post_residual * 7.5; // Moderate penalty for smaller gaps
    }

    // Penalize high number of open bins to minimize bin usage
    if open_bins_count > total_items / 4 {
        score += (open_bins_count as f64) * 20.0; // More aggressive penalty for many open bins
    } else {
        score += (open_bins_count as f64) * 10.0;
    }

    // Reward larger items to encourage better packing
    if item_size > mean_residual as u32 {
        score -= item_size as f64 / 10.0; // Penalize large items to promote better compaction
    }

    score
}

