    let mut score = post_residual as f64;

    // Penalize creating bins with too much free space
    if bin_residual > 75 {
        score += (bin_residual - 75) as f64 * 0.15;
    }

    // Reward using bins efficiently (close to full)
    if bin_residual < 30 {
        score -= (30 - bin_residual) as f64 * 0.25;
    }

    // Penalize if the next item is large and cannot fit in the current bin
    if next_item_size > bin_residual && post_residual == 0 {
        score += (next_item_size - bin_residual) as f64 * 1.75;
    }

    // Reward using bins that can fit future items efficiently
    if fitting_bins_count > 0 {
        score -= (fitting_bins_count as f64 / open_bins_count as f64) * 0.3;
    }

    // Penalize if the mean residual is high, indicating inefficient bin usage
    if mean_residual > 25.0 {
        score += (mean_residual - 25.0) as f64 * 0.1;
    }

    // Reward using fewer bins overall
    if open_bins_count < total_items / 3 {
        score -= (total_items / 3 - open_bins_count) as f64 * 0.75;
    }

    score
}

